    84  TiffIFD::TiffIFD(TiffIFD* parent_, const DataBuffer& data, uint32 offset)
    85      : TiffIFD(parent_) {
    86
    87    // see TiffParser::parse: UINT32_MAX is used to mark the "virtual" top level
    88    // TiffRootIFD in a tiff file
    89    if (offset == UINT32_MAX)
    90      return;
    91
    92    checkOverflow();
    93
    94    ByteStream bs(data);
    95    bs.setPosition(offset);
    96
    97    auto numEntries = bs.getU16(); // Directory entries in this IFD
    98
    99    for (uint32 i = 0; i < numEntries; i++)
   100      parseIFDEntry(&bs);
   101
   102    nextIFD = bs.getU32();
   103  }
