   138  /* This will attempt to parse makernotes and return it as an IFD */
   139  TiffRootIFDOwner TiffIFD::parseMakerNote(TiffEntry* t)
   140  {
   141    // go up the IFD tree and try to find the MAKE entry on each level.
   142    // we can not go all the way to the top first because this partial tree
   143    // is not yet added to the TiffRootIFD.
   144    TiffIFD* p = this;
   145    TiffEntry* makeEntry;
   146    do {
   147      makeEntry = p->getEntryRecursive(MAKE);
   148      p = p->parent;
   149    } while (!makeEntry && p);
   150    string make = makeEntry != nullptr ? trimSpaces(makeEntry->getString()) : "";
   151
   152    ByteStream bs = t->getData();
   153
   154    // helper function for easy setup of ByteStream buffer for the different maker note types
   155    // 'rebase' means position 0 of new stream equals current position
   156    // 'newPosition' is the position where the IFD starts
   157    // 'byteOrderOffset' is the position wher the 2 magic bytes (II/MM) may be found
   158    // 'context' is a string providing error information in case the byte order parsing should fail
   159    auto setup = [&bs](bool rebase, uint32 newPosition,
   160                       uint32 byteOrderOffset = 0,
   161                       const char *context = nullptr) {
   162      if (rebase)
   163        bs = bs.getSubStream(bs.getPosition(), bs.getRemainSize());
   164      if (context)
   165        bs.setInNativeByteOrder(isTiffInNativeByteOrder(bs, byteOrderOffset, context));
   166      bs.skipBytes(newPosition);
   167    };
   168
   169    if (bs.hasPrefix("AOC\0", 4)) {
   170      setup(false, 6, 4, "Pentax makernote");
   171    } else if (bs.hasPrefix("PENTAX", 6)) {
   172      setup(true, 10, 8, "Pentax makernote");
   173    } else if (bs.hasPrefix("FUJIFILM\x0c\x00\x00\x00", 12)) {
   174      bs.setInNativeByteOrder(getHostEndianness() == little);
   175      setup(true, 12);
   176    } else if (bs.hasPrefix("Nikon\x00\x02", 7)) {
   177      // this is Nikon type 3 maker note format
   178      // TODO: implement Nikon type 1 maker note format
   179      // see http://www.ozhiker.com/electronics/pjmt/jpeg_info/nikon_mn.html
   180      bs.skipBytes(10);
   181      setup(true, 8, 0, "Nikon makernote");
   182    } else if (bs.hasPrefix("OLYMPUS", 7)) { // new Olympus
   183      setup(true, 12);
   184    } else if (bs.hasPrefix("OLYMP", 5)) {   // old Olympus
   185      setup(true, 8);
   186    } else if (bs.hasPrefix("EPSON", 5)) {
   187      setup(false, 8);
   188    } else if (bs.hasPatternAt("Exif", 4, 6)) {
   189      // TODO: for none of the rawsamples.ch files from Panasonic is this true, instead their MakerNote start with "Panasonic"
   190      // Panasonic has the word Exif at byte 6, a complete Tiff header starts at byte 12
   191      // This TIFF is 0 offset based
   192      setup(false, 20, 12, "Panosonic makernote");
   193    } else if (make == "SAMSUNG") {
   194      // Samsung has no identification in its MakerNote but starts with the IFD right away
   195      setup(true, 0);
   196    } else {
   197      // cerr << "default MakerNote from " << make << endl; // Canon, Nikon (type 2), Sony, Minolta, Ricoh, Leica, Hasselblad, etc.
   198
   199      // At least one MAKE has not been handled explicitly and starts its MakerNote with an endian prefix: Kodak
   200      if (bs.skipPrefix("II", 2)) {
   201        bs.setInNativeByteOrder( getHostEndianness() == little );
   202      } else if (bs.skipPrefix("MM", 2)) {
   203        bs.setInNativeByteOrder( getHostEndianness() == big );
   204      }
   205    }
   206
   207    // Attempt to parse the rest as an IFD
   208    return make_unique<TiffRootIFD>(this, bs, bs.getPosition());
   209  }
