   231  TiffEntry* __attribute__((pure)) TiffIFD::getEntryRecursive(TiffTag tag) const {
   232    auto i = entries.find(tag);
   233    if (i != entries.end()) {
   234      return i->second.get();
   235    }
   236    for (auto &j : subIFDs) {
   237      TiffEntry *entry = j->getEntryRecursive(tag);
   238      if (entry)
   239        return entry;
   240    }
   241    return nullptr;
   242  }
