   244  void TiffIFD::checkOverflow() {
   245    TiffIFD* p = this;
   246    int i = 0;
   247    while ((p = p->parent) != nullptr) {
   248      i++;
   249      if (i > 5)
   250        ThrowTPE("TiffIFD cascading overflow.");
   251    }
   252  }
   253
   254  void TiffIFD::add(TiffIFDOwner subIFD) {
   255    checkOverflow();
   256    if (subIFDs.size() > 100)
   257      ThrowTPE("TIFF file has too many SubIFDs, probably broken");
   258    subIFD->parent = this;
   259    subIFDs.push_back(move(subIFD));
   260  }

