   107  bool __attribute__((pure)) TiffEntry::isFloat() const {
   108    switch (type) {
   109    case TIFF_FLOAT:
   110    case TIFF_DOUBLE:
   111    case TIFF_RATIONAL:
   112    case TIFF_SRATIONAL:
   113    case TIFF_LONG:
   114    case TIFF_SLONG:
   115    case TIFF_SHORT:
   116    case TIFF_SSHORT:
   117      return true;
   118    default:
   119      return false;
