   123  uchar8 TiffEntry::getByte(uint32 index) const {
   124    if (type != TIFF_BYTE && type != TIFF_UNDEFINED)
   125      ThrowTPE("Wrong type %u encountered. Expected Byte on 0x%x", type, tag);
   126
   127    return data.peekByte(index);
