   178  float TiffEntry::getFloat(uint32 index) const {
   179    if (!isFloat()) {
   180      ThrowTPE("Wrong type 0x%x encountered. Expected Float or something "
   181               "convertible on 0x%x",
   182               type, tag);
   183    }
   184
   185    switch (type) {
   186    case TIFF_DOUBLE: return data.peek<double>(index);
   187    case TIFF_FLOAT:  return data.peek<float>(index);
   188    case TIFF_LONG:
   189    case TIFF_SHORT:
   190      return static_cast<float>(getU32(index));
   191    case TIFF_SLONG:
   192    case TIFF_SSHORT:
   193      return static_cast<float>(getI32(index));
   194    case TIFF_RATIONAL: {
   195      uint32 a = getU32(index*2);
   196      uint32 b = getU32(index*2+1);
   197      return b != 0 ? static_cast<float>(a) / b : 0.0F;
   198    }
   199    case TIFF_SRATIONAL: {
   200      auto a = static_cast<int>(getU32(index * 2));
   201      auto b = static_cast<int>(getU32(index * 2 + 1));
   202      return b ? static_cast<float>(a) / b : 0.0F;
   203    }
   204    default:
   205      // unreachable
   206      return 0.0F;
   207    }
   208  }
